/* Suggested implementation — estimated from a screen recording, not the original CSS. */
/* All values are approximate; display scale assumed 1x. */
/* Markup: .scroller > .scroller__track > the cards repeated twice (two identical copies) for a seamless loop. */
/* Autoplay, dragging, and momentum need the JS driver (JS tab); these rules are layout only. */

body {
  background-color: #FAFAFA; /* estimated, high confidence */
}

.scroller {
  display: flex;
  align-items: center;
  max-width: 760px; /* estimated, medium confidence */
  height: 200px; /* estimated, medium confidence */
  margin-inline: auto;
  overflow: hidden;
  touch-action: pan-y; /* page scroll stays on the other axis */
  user-select: none;
  cursor: grab;
  background-color: #F1F1F4; /* estimated, medium confidence */
}

.scroller:active {
  cursor: grabbing;
}

.scroller__track {
  display: flex;
  flex: none;
  gap: 16px; /* estimated, medium confidence */
  width: max-content;
  will-change: translate;
}

.scroller__card {
  flex: none;
  width: 200px;
  height: 160px;
  background-color: #FFFFFF; /* estimated, medium confidence */
  border-radius: 12px; /* estimated, low confidence */
}

.scroller__text {
  color: #1A1A1A; /* estimated, medium confidence */
  font-size: 16px; /* estimated, low confidence */
}

